import React, { useState } from 'react';

// Create the MultipleStateDemo component here
const MultipleStateDemo = () => {
  // Initialize count state here
  const [count, setCount] = useState<number>(0);

  // Initialize isActive state here
  const [isActive, setIsActive] = useState<boolean>(false);

  // Initialize name state here
  const [name, setName] = useState<string>('');

  // Define incrementCount handler here
  const incrementCount = () => {
    setCount(count + 1);
  };

  // Define toggleActive handler here
  const toggleActive = () => {
    setIsActive(!isActive);
  };

  // Define updateName handler here
  const updateName = (event: React.ChangeEvent<HTMLInputElement>) => {
    setName(event.target.value);
  };

  return (
    <div>
      <h1>Multiple State Variables</h1>
      {/* Add interactive controls here */}
    </div>
  );
};

export default MultipleStateDemo;
